"""Materialize current-agent review decisions into schema-valid contracts."""
import json
from pathlib import Path
import jsonschema,pandas as pd
ROOT=Path(__file__).resolve().parents[2];EXP=ROOT/'try4';dec=json.loads((EXP/'codex_authored/T2/round1_decisions.json').read_text());metrics=pd.read_csv(EXP/'results/phase5_metrics.csv');disc=pd.read_csv(EXP/'results/phase6_regional_discrepancies.csv').set_index('part_id');schema=json.loads((EXP/'schemas/repair_contract.schema.json').read_text())
for d in dec['decisions']:
    pid=d['part_id'];m=metrics[(metrics.part_id==pid)&(metrics.condition=='T1')].iloc[0];feature=json.loads((EXP/f'T1/{pid}/round_0/feature_graph.json').read_text())['features'][0];row=disc.loc[pid]
